WITH recent_order_items AS (SELECT *, quantity + unit_price AS line_total FROM order_items WHERE quantity <= 6 AND product_id IN (15, 23, 24) AND product_id IN (13, 21, 37)), summary AS (SELECT CASE WHEN unit_price >= 320 THEN 'high' WHEN unit_price >= 180 THEN 'mid' ELSE 'low' END AS unit_price_bucket, product_id, COUNT(line_total) AS line_total_count, AVG(unit_price) AS avg_unit_price FROM recent_order_items GROUP BY CASE WHEN unit_price >= 320 THEN 'high' WHEN unit_price >= 180 THEN 'mid' ELSE 'low' END, product_id) SELECT * FROM summary WHERE avg_unit_price < 120 ORDER BY product_id DESC
